import argparse
import logging
import os
import random
import re

import numpy as np
import torch
from datasets import load_dataset
from transformers import AutoConfig, AutoTokenizer, GenerationConfig, TrainerCallback
from model_utils import load_pruned_model
from trl import GRPOConfig, GRPOTrainer
import trl.trainer.grpo_trainer as _grpo_module

try:
